          {
            "id": "s1l8_verses",
            "type": "verse_block",
            "data": {
              "verses": [
                {
                  "num": 1,
                  "arabic": "فَخَرَجَ عَلَى قَوْمِهِ مِنَ الْمِحْرَابِ",
                  "hinglish": "Toh woh apni qaum ke paas mihrab se nikla"
                },
                {
                  "num": 2,
                  "arabic": "مِنَ الْبَشَرِ أَحَدًا",
                  "hinglish": "Insaanon mein se koi ek"
                },
                {
                  "num": 3,
                  "arabic": "وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَدِيدٌ",
                  "hinglish": "Aur un par gussa hai aur unke liye sakht azaab hai"
                },
                {
                  "num": 4,
                  "arabic": "ذَلِكُمْ فِسْقٌ",
                  "hinglish": "Yeh naafarmani hai"
                },
                {
                  "num": 5,
                  "arabic": "مَا لَا يَرْضَى مِنَ الْقَوْلِ",
                  "hinglish": "Na-pasandida baat"
                },
                {
                  "num": 6,
                  "arabic": "اسْتَقَامُوا عَلَى الطَّرِيقَةِ",
                  "hinglish": "Woh tareeqe par qaaim rahe"
                },
                {
                  "num": 7,
                  "arabic": "أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعًا",
                  "hinglish": "Sab taaqat Allah hi ke liye hai"
                },
                {
                  "num": 8,
                  "arabic": "فَجَزَاؤُهُ جَهَنَّمُ",
                  "hinglish": "Toh uska badla jahannam hai"
                },
                {
                  "num": 9,
                  "arabic": "إِذْ هُمَا فِي الْغَارِ",
                  "hinglish": "Jab woh dono ghaar mein the"
                },
                {
                  "num": 10,
                  "arabic": "ثَلَاثَ مَرَّاتٍ مِنْ قَبْلِ صَلَاةِ الْفَجْرِ",
                  "hinglish": "Teen baar fajr ki namaz se pehle"
                },
                {
                  "num": 11,
                  "arabic": "جِئْنَاكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيرًا",
                  "hinglish": "Hum aap ke paas haq aur behtareen wazaahat ke saath aaye"
                },
                {
                  "num": 12,
                  "arabic": "لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ",
                  "hinglish": "Taaki aap par koi tangi na ho"
                }
              ]
            }
          }
