          {
            "id": "s1l10_verses",
            "type": "verse_block",
            "data": {
              "verses": [
                {
                  "num": 1,
                  "arabic": "لَا تَسْأَلُوا عَنْ أَشْيَاءَ",
                  "hinglish": "Ashyaa ke baare mein na poocho"
                },
                {
                  "num": 2,
                  "arabic": "لَهُمْ قُلُوبٌ لَا يَفْقَهُونَ بِهَا",
                  "hinglish": "Unke paas dil hain jinse woh samajhte nahi"
                },
                {
                  "num": 3,
                  "arabic": "وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ",
                  "hinglish": "Aur Allah hi ki taraf sab kaam lautaaye jaate hain"
                },
                {
                  "num": 4,
                  "arabic": "وَأَنَّ الْمَسَاجِدَ لِلَّهِ",
                  "hinglish": "Aur beshak masajid Allah ke liye hain"
                },
                {
                  "num": 5,
                  "arabic": "وَإِذَا النُّفُوسُ زُوِّجَتْ",
                  "hinglish": "Aur jab jaanein jodi jayeingi"
                },
                {
                  "num": 6,
                  "arabic": "وَلَا تَنَابَزُوا بِالْأَلْقَابِ",
                  "hinglish": "Aur ek doosre ko bure alqab se na pukaro"
                },
                {
                  "num": 7,
                  "arabic": "وَلَهُمْ أَعْمَالٌ مِنْ دُونِ ذَلِكَ",
                  "hinglish": "Aur unke liye iske ilawa bhi a'maal hain"
                },
                {
                  "num": 8,
                  "arabic": "تِلْكَ حُدُودُ اللَّهِ فَلَا تَقْرَبُوهَا",
                  "hinglish": "Yeh Allah ki hudood hain toh unke qareeb na jao"
                },
                {
                  "num": 9,
                  "arabic": "فَانْظُرْ إِلَى آثَارِ رَحْمَةِ اللَّهِ",
                  "hinglish": "Toh Allah ki rehmat ke aathaar ki taraf dekho"
                }
              ]
            }
          }
