          {
            "id": "s1l11_q5_verses",
            "type": "verse_block",
            "data": {
              "verses": [
                {
                  "num": 1,
                  "arabic": "﴿ وَمِنْ كُلِّ الثَّمَرَاتِ جَعَلَ فِيهَا ﴾",
                  "hinglish": "Aur har qism ke phalon se us mein banaye"
                },
                {
                  "num": 2,
                  "arabic": "﴿ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ ﴾",
                  "hinglish": "Allah unhe unke a'maal afsoos bana kar dikhaayega"
                },
                {
                  "num": 3,
                  "arabic": "﴿ يَكْفُرُونَ بِآيَاتِ اللَّهِ ﴾",
                  "hinglish": "Woh Allah ki aayaat ka inkaar karte hain"
                },
                {
                  "num": 4,
                  "arabic": "﴿ سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا ﴾",
                  "hinglish": "Anqareeb ham unhe aise baagho mein daakhil karenge jinke neeche..."
                },
                {
                  "num": 5,
                  "arabic": "﴿ وَعَلَامَاتٍ وَبِالنَّجْمِ هُمْ يَهْتَدُونَ ﴾",
                  "hinglish": "Aur nishaniyan, aur sitare ke zariye woh rasta paate hain"
                },
                {
                  "num": 6,
                  "arabic": "﴿ لَفَتَحْنَا عَلَيْهِمْ بَرَكَاتٍ ﴾",
                  "hinglish": "To zaroor ham un par barkatein khol dete"
                },
                {
                  "num": 7,
                  "arabic": "﴿ فَتَلَقَّى آدَمُ مِنْ رَبِّهِ كَلِمَاتٍ ﴾",
                  "hinglish": "Phir Aadam (A.S.) ne apne Rabb se kuch kalimat seekh liye"
                },
                {
                  "num": 8,
                  "arabic": "﴿ يُخْرِجُهُمْ مِنَ الظُّلُمَاتِ إِلَى النُّورِ ﴾",
                  "hinglish": "Woh unhe andheron se roshni ki taraf nikaalta hai"
                },
                {
                  "num": 9,
                  "arabic": "﴿ فَأَصَابَهُمْ سَيِّئَاتُ مَا عَمِلُوا ﴾",
                  "hinglish": "To un par unke kiye hue a'maal ki buraiyaan aa padin"
                }
              ]
            }
          }
